// src/lib/mcp/tools/list-services.ts
var CATALOGS = { it: serviceGroups, en: serviceGroupsEN, pt: serviceGroupsPT };
var PAGES = {
  it: "https://businessmatching.global/Our_Services",
  en: "https://businessmatching.global/Our_Services",
  pt: "https://businessmatching.global/Our_Services"
};
var list_services_default = defineTool4({
  name: "list_services",
  title: "List Business Matching Global services",
  description: "List the services Business Matching Global offers (market research, company verification, buyer/supplier search, business matching, import/export support, business travel), with what each includes, who it is for and the starting price.",
  inputSchema: {
    language: z4.enum(["it", "en", "pt"]).nullable().describe("Catalogue language (default en)."),
    query: z4.string().nullable().describe("Optional keyword to filter services by name or description.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ language, query }) => {
    const lang = language ?? "en";
    const groups = CATALOGS[lang];
    const needle = query?.trim().toLowerCase() ?? "";
    const sections = [];
    const structured = [];
    for (const group of groups) {
      for (const item of group.items) {
        const haystack = `${item.name} ${item.tagline} ${item.bullets.join(" ")}`.toLowerCase();
        if (needle && !haystack.includes(needle)) continue;
        sections.push(
          [
            `### ${group.num} \xB7 ${item.name} \u2014 ${item.price}`,
            item.tagline,
            item.bullets.map((b) => `- ${b}`).join("\n"),
            item.audience.length ? `For: ${item.audience.join("; ")}` : "",
            item.examples ?? ""
          ].filter(Boolean).join("\n")
        );
        structured.push({
          group: group.label,
          name: item.name,
          tagline: item.tagline,
          price: item.price,
          bullets: item.bullets
        });
      }
    }
    const text = sections.length ? `${sections.join("\n\n")}

Full catalogue: ${PAGES[lang]}` : `No service matches that query. Full catalogue: ${PAGES[lang]}`;
    return { content: [{ type: "text", text }], structuredContent: { services: structured } };
  }
});

